// arXiv Atom XML をパースして [{title, url, description, source}] に変換
const raw = $input.first().json.data || '';
const entries = [];
const entryRegex = /<entry>([\s\S]*?)<\/entry>/g;
let match;
while ((match = entryRegex.exec(raw)) !== null) {
  const block = match[1];
  const titleMatch = block.match(/<title[^>]*>([\s\S]*?)<\/title>/);
  const linkMatch = block.match(/<id>([\s\S]*?)<\/id>/);
  const summaryMatch = block.match(/<summary[^>]*>([\s\S]*?)<\/summary>/);
  const title = (titleMatch ? titleMatch[1] : '').replace(/\s+/g, ' ').trim();
  const url = (linkMatch ? linkMatch[1] : '').trim();
  const desc = (summaryMatch ? summaryMatch[1] : '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim().substring(0, 200);
  if (title && url) {
    entries.push({ json: { title, url, description: desc, source: 'arxiv' } });
  }
  if (entries.length >= 30) break;
}
if (entries.length === 0) {
  return [{ json: { title: 'arXiv empty', url: '', description: '', source: 'arxiv' } }];
}
return entries;

// 全ソースの記事を集約し、URL正規化+既存排除+重複統合
// WaitAllFeeds(Merge)経由で全フィード完了後に実行される
const existingData = $('FetchExistingURLs').first().json;
const existingURLs = new Set((existingData.data || []).map(u => u.toLowerCase()));

function normalizeUrl(url) {
  try {
    const u = new URL(url);
    let host = u.hostname.replace(/^www\./, '');
    const tracking = new Set(['utm_source','utm_medium','utm_campaign','utm_term','utm_content','ref','source','via','fbclid','gclid']);
    const params = new URLSearchParams(u.search);
    for (const key of [...params.keys()]) {
      if (tracking.has(key.toLowerCase())) params.delete(key);
    }
    let path = u.pathname.replace(/\/+$/, '') || '/';
    const qs = params.toString();
    return 'https://' + host + path + (qs ? '?' + qs : '');
  } catch { return url; }
}

function extractRssItems(nodeName, sourceName) {
  try {
    const items = $(nodeName).all();
    return items.map(item => {
      const d = item.json;
      return {
        title: (d.title || '').substring(0, 200),
        url: d.link || d.url || '',
        description: (d.contentSnippet || d.description || '').replace(/<[^>]+>/g, '').substring(0, 200),
        source: sourceName
      };
    });
  } catch (e) {
    return [];
  }
}

const rssItems = [
  ...extractRssItems('FetchHN', 'hackernews'),
  ...extractRssItems('FetchHatena', 'hatena'),
  ...extractRssItems('FetchZenn', 'zenn'),
  ...extractRssItems('FetchLobsters', 'lobsters')
];

// arXiv: ParseArXiv または ArXivFallback のどちらかから取得
let arxivItems = [];
try {
  arxivItems = $('ParseArXiv').all().map(item => item.json);
} catch {
  try {
    arxivItems = $('ArXivFallback').all().map(item => item.json);
  } catch { arxivItems = []; }
}

// 重複排除
const seen = new Set();
const articles = [];
for (const item of rssItems) {
  if (!item.url || !item.title) continue;
  const norm = normalizeUrl(item.url);
  if (seen.has(norm) || existingURLs.has(norm.toLowerCase())) continue;
  seen.add(norm);
  articles.push(item);
}

const papers = [];
for (const item of arxivItems) {
  if (!item.url || !item.title) continue;
  const norm = normalizeUrl(item.url);
  if (seen.has(norm) || existingURLs.has(norm.toLowerCase())) continue;
  seen.add(norm);
  papers.push(item);
}

return [{ json: { articles, papers, articleCount: articles.length, paperCount: papers.length } }];

const data = $input.first().json;
const articles = data.articles || [];
const papers = data.papers || [];

const articleLines = articles.map((a, i) =>
  `${i + 1}. [${a.source}] ${a.title}${a.description ? '
   ' + a.description.substring(0, 100) : ''}`
).join('
');

const paperLines = papers.map((p, i) =>
  `${i + 1}. ${p.title}${p.description ? '
   ' + p.description.substring(0, 100) : ''}`
).join('
');

const prompt = `あなたはテック系キュレーターです。以下の記事候補から、今日のトップ6件と注目論文1件を選んでください。

## 選定ルール

### Step 1: 重複統合
同じトピックの記事が複数ソースにある場合、1つに統合してください。

### Step 2: テーマ別クラスタリング
記事を内容でクラスタ分けしてください。偏りがある場合はそれがトレンドの信号です。

### Step 3: 2軸で選定
- 軸1（テーマ）: 最低5つの異なるテーマから選ぶ
- 軸2（読者への作用）: 以下の4種から最低3種を含める
  - 「すぐ動く」: 脆弱性、破壊的変更、重要リリース（1-2件）
  - 「知見が増える」: やってみた、実践記、チュートリアル（1-2件）
  - 「視点が変わる」: 議論提起、意外な事実、逆張り（1-2件）
  - 「触りたくなる」: 新ツール、ゲーム、デモ（1-2件）

### インパクトスコア基準
- 10: 業界全体が動く（主要FWのRCE、GPT-5リリース）
- 8-9: 多くの開発者に影響
- 6-7: 対応必要 or 注目イベント
- 4-5: 特定分野の人に重要
- 1-3: 面白いが行動不要

## 記事候補（${articles.length}件）
${articleLines}

## 論文候補（${papers.length}件）
${paperLines}

## 出力形式（JSON）
{"clusters":[{"theme":"テーマ名","count":1}],"articles":[{"index":1,"title":"タイトル","source":"ソース","impact":5,"effect":"すぐ動く","reason":"選定理由"}],"paper":{"index":1,"title":"タイトル","impact":5,"reason":"選定理由"}}
JSONのみ出力してください。`;

const geminiBody = JSON.stringify({
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.3, responseMimeType: 'application/json' }
});

return [{ json: { geminiBody, articles, papers } }];

const geminiResponse = $input.first().json;
const originalData = $('PrepareSelectionPrompt').first().json;
const articles = originalData.articles;
const papers = originalData.papers;

// Geminiレスポンス解析
const responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
if (!responseText) {
  throw new Error('ParseSelection: Geminiレスポンスが空。response: ' + JSON.stringify(geminiResponse).substring(0, 500));
}

let selection;
try {
  selection = JSON.parse(responseText);
} catch (e) {
  throw new Error('ParseSelection: JSONパース失敗。text: ' + responseText.substring(0, 300));
}

// タイトルベースでマッチ（indexが信頼できない場合のフォールバック）
function findByTitle(list, title) {
  if (!title) return null;
  const norm = title.toLowerCase().trim();
  return list.find(a => a.title && a.title.toLowerCase().trim() === norm) || null;
}

const results = [];
for (const a of (selection.articles || []).slice(0, 6)) {
  const idx = (a.index || 1) - 1;
  let original = articles[idx];
  // indexがずれている場合、タイトルで探す
  if (!original || (a.title && original.title !== a.title)) {
    const byTitle = findByTitle(articles, a.title);
    if (byTitle) original = byTitle;
  }
  if (!original) continue;
  results.push({ json: {
    url: original.url, title: a.title || original.title,
    source: original.source, impact: a.impact || 5, isPaper: 0
  }});
}

const paper = selection.paper;
if (paper && papers.length > 0) {
  const pidx = (paper.index || 1) - 1;
  let original = papers[pidx] || null;
  if (!original || (paper.title && original.title !== paper.title)) {
    const byTitle = findByTitle(papers, paper.title);
    if (byTitle) original = byTitle;
  }
  if (!original) original = papers[0];
  results.push({ json: {
    url: original.url, title: paper.title || original.title,
    source: 'arxiv', impact: paper.impact || 5, isPaper: 1
  }});
}

if (results.length === 0) {
  throw new Error('ParseSelection: 選定結果が0件\narticles候補: ' + articles.length + '件, papers候補: ' + papers.length + '件\nGemini selection: ' + JSON.stringify(selection).substring(0, 500));
}
return results;

// HTML本文から<p>タグ内容を抽出し、元データとマージして1件に集約
const fetchResults = $input.all();
const originals = $('ParseSelection').all();

const combined = [];
for (let i = 0; i < originals.length; i++) {
  const orig = originals[i].json;
  const fetched = fetchResults[i]?.json || {};
  let fulltext = '';
  const rawHtml = fetched.data || '';
  if (rawHtml && typeof rawHtml === 'string') {
    const paragraphs = rawHtml.match(/<p[^>]*>[\s\S]*?<\/p>/gi) || [];
    fulltext = paragraphs
      .map(p => p.replace(/<[^>]+>/g, '').trim())
      .filter(t => t.length > 20)
      .join('\n')
      .substring(0, 3000);
  }
  if (!fulltext) fulltext = '(本文取得失敗)';
  combined.push({
    url: orig.url, title: orig.title, source: orig.source,
    impact: orig.impact, isPaper: orig.isPaper, fulltext
  });
}
return [{ json: { items: combined } }];

const geminiResponse = $input.first().json;
const originalItems = $('PrepareSummaryPrompt').first().json.items;

let summaries;
try {
  const responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
  summaries = JSON.parse(responseText);
} catch (e) {
  throw new Error('FormatArticles: Gemini要約結果のパースに失敗: ' + e.message);
}

const apiBody = [];
for (const s of summaries) {
  const idx = (s.article_index || 1) - 1;
  const orig = originalItems[idx];
  if (!orig) continue;
  // title_ja があれば翻訳タイトルを使用、なければ元タイトル
  const title = s.title_ja || orig.title;
  apiBody.push({
    url: orig.url, title, source: orig.source,
    summary: s.summary || '', comment: s.comment || '',
    tags: s.tags || [], impact: orig.impact || 5,
    isPaper: orig.isPaper || 0,
    publishedAt: new Date().toISOString().substring(0, 10)
  });
}

if (apiBody.length === 0) throw new Error('FormatArticles: 整形後の記事が0件');
return [{ json: { requestBody: JSON.stringify(apiBody), articleCount: apiBody.length } }];

const result = $input.first().json;
const count = $('FormatArticles').first().json.articleCount || 0;
const msg = result.ok
  ? '✅ shirankedo 記事更新完了: ' + count + '件追加'
  : '❌ shirankedo 記事投入失敗: ' + (result.error || 'unknown');
return [{ json: { message: msg } }];

// NVD APIレスポンスをパース（CVSS >= 8.0 フィルタ + 既存CVE除外）
const nvdData = $('FetchNVD').first().json;
const existingData = $('FetchExistingCVEs').first().json;
const existingIds = new Set(existingData.data || []);
const vulns = nvdData.vulnerabilities || [];
const results = [];
for (const v of vulns) {
  const cve = v.cve || {};
  const cveId = cve.id || '';
  if (existingIds.has(cveId)) continue;
  const descriptions = cve.descriptions || [];
  const enDesc = descriptions.find(d => d.lang === 'en');
  const description = enDesc ? enDesc.value : '';
  const metrics = cve.metrics || {};
  let cvssScore = null;
  if (metrics.cvssMetricV31 && metrics.cvssMetricV31.length > 0) {
    cvssScore = metrics.cvssMetricV31[0].cvssData?.baseScore;
  } else if (metrics.cvssMetricV30 && metrics.cvssMetricV30.length > 0) {
    cvssScore = metrics.cvssMetricV30[0].cvssData?.baseScore;
  }
  if (cvssScore === null || cvssScore < 8.0) continue;
  const publishedAt = cve.published ? cve.published.substring(0, 10) : '';
  if (cveId && description) {
    results.push({ cveId, description: description.substring(0, 500), cvssScore, publishedAt });
  }
}
return [{ json: { vulnerabilities: results, count: results.length } }];

// Geminiバッチ翻訳プロンプトを構築
const data = $input.first().json;
const vulns = data.vulnerabilities || [];
if (vulns.length === 0) {
  return [{ json: { requestBody: '[]', count: 0, skip: true } }];
}
const vulnText = vulns.map((v, i) => `${i + 1}. [${v.cveId}] (CVSS: ${v.cvssScore || 'N/A'})
   ${v.description}`).join('

');
const prompt = `以下のNVD脆弱性情報の英語説明を、簡潔な日本語タイトル（30～50字）に変換してください。
技術用語はカタカナまたは英語のまま残してください。

## 脆弱性一覧（${vulns.length}件）
${vulnText}

## 出力形式（JSON配列）
[{"index": 1, "title": "日本語タイトル"}]
JSONのみ出力してください。`;
const geminiBody = JSON.stringify({ contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0.2, responseMimeType: 'application/json' } });
return [{ json: { geminiBody, vulnerabilities: vulns, count: vulns.length, skip: false } }];

// Gemini翻訳結果とCVEデータをマージ
const data = $('PrepareNVDTranslation').first().json;
const vulns = data.vulnerabilities;
const geminiResponse = $input.first().json;
let titles = [];
try {
  const responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
  titles = JSON.parse(responseText);
} catch (e) {
  titles = vulns.map((v, i) => ({ index: i + 1, title: v.description.substring(0, 50) }));
}
const apiBody = vulns.map((v, i) => {
  const titleEntry = titles.find(t => t.index === i + 1);
  return { cveId: v.cveId, title: titleEntry ? titleEntry.title : v.description.substring(0, 50), cvssScore: v.cvssScore, publishedAt: v.publishedAt };
});
return [{ json: { requestBody: JSON.stringify(apiBody), count: apiBody.length, vulnerabilities: apiBody } }];

const input = $input.first().json;
const count = $('MergeVulnPaths').first().json.count || 0;
const isError = !!input.error || (input.statusCode && input.statusCode >= 400);
const msg = !isError
  ? `✅ shirankedo 脆弱性更新完了: ${count}件`
  : `❌ shirankedo 脆弱性投入失敗: ${typeof input.error === 'object' ? JSON.stringify(input.error) : (input.error || input.message || 'unknown')}`;
return [{ json: { message: msg } }];

// tracking-reposからGraphQLバッチクエリを構築（40リポ/バッチ）
const response = $input.first().json;
const repos = response.data || response || [];
const repoList = Array.isArray(repos) ? repos.map(r => typeof r === 'string' ? r : (r.repo || '')) : [];
const valid = repoList.filter(r => r && r.includes('/'));
if (valid.length === 0) {
  return [{ json: { releases: [], count: 0, empty: true } }];
}
const BATCH_SIZE = 40;
const batches = [];
for (let i = 0; i < valid.length; i += BATCH_SIZE) {
  const batch = valid.slice(i, i + BATCH_SIZE);
  const parts = batch.map((repo, idx) => {
    const [owner, name] = repo.split('/');
    const alias = `r${Math.floor(i / BATCH_SIZE)}_${idx}`;
    return `${alias}: repository(owner: "${owner}", name: "${name}") { nameWithOwner releases(first: 5, orderBy: {field: CREATED_AT, direction: DESC}) { nodes { tagName isPrerelease publishedAt name } } }`;
  });
  batches.push({ json: { query: `{${parts.join(' ')}}`, batchIndex: Math.floor(i / BATCH_SIZE) } });
}
return batches;

// 各バッチのGraphQL結果からリリースを抽出してstaticDataに蓄積
const staticData = $getWorkflowStaticData('global');
if (!staticData.releases) staticData.releases = [];
const now = new Date();
const cutoff = new Date(now.getTime() - 72 * 60 * 60 * 1000).toISOString();
const data = $input.first().json.data || $input.first().json || {};
for (const key of Object.keys(data)) {
  const repo = data[key];
  if (!repo || !repo.releases) continue;
  const repoName = repo.nameWithOwner;
  for (const rel of repo.releases.nodes) {
    if (rel.isPrerelease) continue;
    if (!rel.publishedAt || rel.publishedAt < cutoff) continue;
    const tag = rel.tagName;
    const rawVer = tag.includes('@') ? tag.split('@').pop() : tag;
    const version = rawVer.replace(/^v/, '');
    const parts = version.split('.');
    let type = null;
    if (parts.length >= 3) {
      const [maj, min, pat] = parts.map(p => parseInt(p));
      if (!isNaN(maj) && !isNaN(min) && !isNaN(pat)) {
        if (min === 0 && pat === 0) type = 'major';
        else if (pat === 0) type = 'minor';
      }
    } else if (parts.length === 2) {
      if (!isNaN(parseInt(parts[0])) && !isNaN(parseInt(parts[1]))) type = 'minor';
    }
    if (!type) continue;
    staticData.releases.push({ repo: repoName, tag, version, type, publishedAt: rel.publishedAt.substring(0, 10) });
  }
}
return $input.all();

// SplitInBatches完了後: staticDataから蓄積リリースを取得
const staticData = $getWorkflowStaticData('global');
const releases = staticData.releases || [];
staticData.releases = [];
return [{ json: { requestBody: JSON.stringify(releases), count: releases.length, releases } }];

const input = $input.first().json;
const count = $('MergeReleasePaths').first().json.count || 0;
const isError = !!input.error || (input.statusCode && input.statusCode >= 400);
const msg = !isError
  ? `✅ shirankedo リリース更新完了: ${count}件`
  : `❌ shirankedo リリース投入失敗: ${typeof input.error === 'object' ? JSON.stringify(input.error) : (input.error || input.message || 'unknown')}`;
return [{ json: { message: msg } }];

// B(脆弱性)とC(リリース)の結果からセキュリティ日次コメントを生成
let vulns = [];
let releases = [];
try { vulns = $('MergeVulnPaths').first().json.vulnerabilities || []; } catch {}
try { releases = $('MergeReleasePaths').first().json.releases || []; } catch {}
const vulnText = vulns.length > 0
  ? vulns.map(v => `- ${v.cve_id}: ${v.title} (CVSS: ${v.cvss_score || 'N/A'})`).join('
')
  : '（本日のCRITICAL脆弱性はなし）';
const relText = releases.length > 0
  ? releases.map(r => `- ${r.repo} ${r.tag} (${r.type})`).join('
')
  : '（本日のメジャー/マイナーリリースはなし）';
const prompt = `あなたはギャルのセキュリティアナリストです。今日のセキュリティ状況をまとめてコメントしてください。

## 今日の脆弱性（${vulns.length}件）
${vulnText}

## 今日のリリース（${releases.length}件）
${relText}

## コメントルール
- 200字以内
## 口調ルール
「ギャルっぽい記号を貼り付けた文章」ではなく「ギャルが実際に喋りそうな文章」を書け。
- 一人称「うち」。語尾「〜じゃん」「〜っしょ」「〜くない？」「〜じゃね？」「〜だし」
- 強調「マジで」「ガチで」「超」「鬼」。感嘆「やば」「えぐ」「つよ」（体言止め）
- テンションに緩急をつけろ。常時MAXはウソくさい。重い話は静かにしんどがれ
- 絵文字は0〜1個。使わなくていい。効かせる時だけ
- 「おけまる」「わかりみが深い」「あーし」は古い。使うな
- 同じ語彙の連打禁止。「マジ？」「ヤバすぎ！」を毎回使うな
- 禁止: 「〜だわ」「あたし」、敬語
- 脆弱性が多い日は注意喚起、リリースが目立つ日はアプデ推奨
- 何もない日は「今日は平和っしょ」的なコメント

## 出力形式（JSON）
{"comment": "コメント本文", "vuln_ids": ["CVE-2026-XXXXX"], "release_ids": []}
vuln_idsは言及したCVE-IDのリスト、release_idsは空配列。
JSONのみ出力してください。`;
const geminiBody = JSON.stringify({ contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0.7, responseMimeType: 'application/json' } });
return [{ json: { geminiBody, vulnCount: vulns.length, releaseCount: releases.length } }];

const geminiResponse = $input.first().json;
let result;
try {
  const responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
  result = JSON.parse(responseText);
} catch (e) {
  throw new Error('FormatSecurityDaily: Geminiレスポンスのパースに失敗: ' + e.message);
}
const apiBody = { comment: result.comment || '', vuln_ids: result.vuln_ids || [], release_ids: result.release_ids || [] };
return [{ json: { requestBody: JSON.stringify(apiBody), comment: apiBody.comment } }];

const input = $input.first().json;
const vulnCount = $('PrepareSecurityComment').first().json.vulnCount || 0;
const releaseCount = $('PrepareSecurityComment').first().json.releaseCount || 0;
const isError = !!input.error || (input.statusCode && input.statusCode >= 400);
const msg = !isError
  ? `✅ shirankedo セキュリティ日次更新完了（脆弱性${vulnCount}件、リリース${releaseCount}件）`
  : `❌ shirankedo セキュリティ日次投入失敗: ${input.error || input.message || 'unknown'}`;
return [{ json: { message: msg } }];
